  1009	/**
  1010	 * @brief 把"帧外增量还没进 R"的记账补烘掉（限频窗口内先留着）。
  1011	 *
  1012	 * @details 由 200 ms 的航向拍调用（`vmap_view_set_heading`），所以即使某次增量
  1013	 *          之后再没有任何失效，内容也会在窗口到期后的下一拍上屏；不会永远停在旧版本。
  1014	 */
  1015	static void vmap_rot_service(vmap_view_t * view)
  1016	{
  1017	    bool angle;
  1018	
  1019	    if (view == NULL || !view->heading_up) {
  1020	        return;
  1021	    }
  1022	    angle = (view->want_rot10 != view->rot10);
  1023	    if (!angle && !view->rot_pending) {
  1024	        return;
  1025	    }
  1026	    if (view->pump_phase != 0u || view->rcanvas == NULL
  1027	        || view->render_rev == 0u
  1028	        || lv_obj_has_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN)) {
  1029	        return;                 /* 帧在飞（帧末会烘）或还没显示/还没有首帧 */
  1030	    }
  1031	    if (view->last_bake_ms != 0u
  1032	        && lv_tick_elaps(view->last_bake_ms) < VMAP_ROT_BAKE_MIN_MS) {
  1033	        return;                 /* 限频窗口未到：下一拍再来 */
  1034	    }
  1035	    /*
  1036	     * 待应用角度与"帧外增量"合并到**同一次**重烘：否则先用旧角度烘一次增量会刷新
  1037	     * `last_bake_ms`，把角度请求一直挡在窗口外（持续记录时地图永远保持旧朝向）。
  1038	     * 角度**成功烘完才提交**：EPIC 旋转失败时保留 want_rot10，下一拍自动重试，
  1039	     * 不会把请求悄悄丢掉（否则静止时再没有别的东西会触发重烘）。
  1040	     */
  1041	    {
  1042	        const int32_t prev_rot10 = view->rot10;
  1043	
  1044	        view->rot10 = view->want_rot10;
  1045	        if (!vmap_rot_full(view)) {
  1046	            /* 失败记账在 `vmap_rot_full()` 里统一做（见那里的注释）。 */
  1047	            view->rot10 = prev_rot10;
  1048	        }
  1049	    }
  1050	}
