  1052	/**
  1053	 * @brief 跟车：R 里的内容该位移 (-R(θ)·Δpan)；余量够只挪对象，不够重烘。
  1054	 */
  1055	static void vmap_rot_track(vmap_view_t * view)
  1056	{
  1057	    const double th = (double)view->r_rot10 * 0.1 * M_PI / 180.0;
  1058	    const double c = cos(th);
  1059	    const double s = sin(th);
  1060	    const double dpx = view->pan_dx - view->r_pan_x;
  1061	    const double dpy = view->pan_dy - view->r_pan_y;
  1062	    const int32_t sx = (int32_t)lround(-(c * dpx - s * dpy));
  1063	    const int32_t sy = (int32_t)lround(-(s * dpx + c * dpy));
  1064	    const int32_t lim = view->r_margin - VMAP_ROT_TRACK_GUARD;
  1065	
  1066	    if (view->rot10 != view->r_rot10
  1067	        || abs((int)sx) > lim || abs((int)sy) > lim) {
  1068	        vmap_rot_full(view);    /* 角度变了、或余量用完了；失败记账在它内部 */
  1069	        return;
  1070	    }
  1071	
  1072	    vmap_rot_place(view, sx, sy);
  1073	}
