   199	void lv_epic_poll_pending_completion(void)
   200	{
   201	    EPIC_HandleTypeDef * epic = lv_epic_get_handle();
   202	
   203	    if(epic == NULL || epic->Instance == NULL) {
   204	        return;
   205	    }
   206	
   207	    if(epic->IntXferCpltCallback == NULL && epic->XferCpltCallback == NULL) {
   208	        return;
   209	    }
   210	
   211	    uint32_t eof = epic->Instance->EOF_IRQ;
   212	    bool irq_pending = ((eof & EPIC_EOF_IRQ_IRQ_STATUS_Msk) != 0U)
   213	                       || ((eof & EPIC_EOF_IRQ_IRQ_CAUSE_Msk) != 0U);
   214	    bool hw_idle = ((epic->Instance->STATUS & EPIC_STATUS_IA_BUSY_Msk) == 0U);
   215	
   216	    if(irq_pending || hw_idle) {
   217	        HAL_EPIC_IRQHandler(epic);
   218	    }
   219	}
